<script setup>
import {computed,nextTick,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import {ElMessage} from 'element-plus';
import UiIcon from './UiIcon.vue';
import AssistantAnswer from './AssistantAnswer.vue';
import ShoppingLinks from './ShoppingLinks.vue';
import ProductImage from './ProductImage.vue';
import {api,categories,scenarioWeights} from './api';
import {money,observed} from './reportFormat';
import {createVoiceInput} from './voiceInput';
import {contextSignature,applyAdvisorTurn,prepareNavigation} from './advisorContext';
const props=defineProps({context:Object});const emit=defineEmits(['model-change','navigate']);
const browser=typeof window==='undefined'?{}:window;
const status=ref({configured:false,model:''}),settingsOpen=ref(false),settings=reactive({base_url:'https://api.openai.com/v1',model:'gpt-4.1-mini',api_key:'',transcription_model:'whisper-1'}),saving=ref(false),testing=ref(false),connection=ref(''),busy=ref(false),chatEl=ref(null),autoSpeak=ref(false),speaking=ref(false),pool=ref([]),poolLoading=ref(false),editing=ref(false),applying=ref(false),quoteProduct=ref(null),localNotice=ref('');
const edit=reactive({category:props.context.profile.category,budget:props.context.profile.budget,scenario:props.context.profile.scenario,needs:props.context.profile.needs});
const options=computed(()=>{const map=new Map([...pool.value,...props.context.products].filter(p=>p.category===props.context.profile.category).map(p=>[p.id,p]));return [...map.values()].sort((a,b)=>(b.score||0)-(a.score||0))});
const selected=computed(()=>options.value.find(p=>p.id===props.context.selectedId));
const peer=computed(()=>props.context.comparePair?.find(p=>p.id!==props.context.selectedId&&p.category===props.context.profile.category));
const priorities=computed(()=>Object.entries(props.context.profile.weights||{}).filter(([k,v])=>v>0).sort((a,b)=>b[1]-a[1]).slice(0,3));
const metricNames={performance:'配置',price:'预算',battery:'续航',portability:'便携',ease:'上手',camera:'影像',screen:'屏幕'};
const suggestions=computed(()=>props.context.assistantSuggestions?.length?props.context.assistantSuggestions:selected.value?[`为什么考虑${selected.value.name}？`,'它和另一款有什么区别？','换个便宜点的','买它之前要注意什么？']:['按当前预算推荐几款','更看重续航，重新筛选','怎么核验报价与配置？']);
const latestMode=computed(()=>[...props.context.chatMessages].reverse().find(m=>m.role==='assistant'&&m.data)?.data.mode);
const canSpeak=!!browser.speechSynthesis;
let controller,requestSerial=0,poolSerial=0,disposed=false,poolTimer;
function basis(){return contextSignature(props.context)}
function stale(message){return !!message.basis&&message.basis!==basis()}
async function scroll(){await nextTick();if(chatEl.value)chatEl.value.scrollTop=chatEl.value.scrollHeight}
function stopSpeaking(){browser.speechSynthesis?.cancel();speaking.value=false}
function speak(text){if(!canSpeak)return;stopSpeaking();const utterance=new browser.SpeechSynthesisUtterance(text.replace(/[#*`]/g,''));utterance.lang='zh-CN';utterance.rate=1;const chosen=browser.speechSynthesis.getVoices().find(v=>v.lang.startsWith('zh'));if(chosen)utterance.voice=chosen;utterance.onend=utterance.onerror=()=>speaking.value=false;speaking.value=true;browser.speechSynthesis.speak(utterance)}
const voice=createVoiceInput({browser,media:typeof navigator==='undefined'?undefined:navigator.mediaDevices,getDraft:()=>props.context.chatDraft,setDraft:value=>props.context.chatDraft=value,configured:()=>status.value.configured,transcribe:async(blob,mime)=>{const data=new FormData();data.append('audio',blob,mime.includes('mp4')?'voice.m4a':'voice.webm');const result=await api('assistant/transcribe',undefined,{method:'POST',body:data});return result.text}});
const {mode:voiceMode,phase:voicePhase,notice:voiceNotice,elapsed:voiceElapsed}=voice;
async function voiceClick(){stopSpeaking();if(voicePhase.value==='listening')voice.stop();else if(voicePhase.value==='idle')await voice.start()}
async function refresh(){try{status.value=await api('assistant/config');Object.assign(settings,{base_url:status.value.base_url,model:status.value.model,transcription_model:status.value.transcription_model,api_key:''});emit('model-change',status.value.configured)}catch(e){ElMessage.error(e.message)}}
async function save(){saving.value=true;connection.value='';try{status.value=await api('assistant/config',{...settings});settings.api_key='';emit('model-change',status.value.configured);connection.value='已保存设置。测试连接成功后，可开始真实模型问答。';ElMessage.success('设置已保存')}catch(e){connection.value=e.message}finally{saving.value=false}}
async function test(){testing.value=true;connection.value='';try{const result=await api('assistant/test',{...settings});connection.value=result.message+' · '+result.model+' · '+result.reply;ElMessage.success('模型服务测试成功')}catch(e){connection.value=e.message}finally{testing.value=false}}
async function loadPool(){const token=++poolSerial;poolLoading.value=true;try{const result=await api('recommend',{...props.context.profile,purpose:'compare'});if(token===poolSerial&&!disposed)pool.value=result.products}catch(e){if(!disposed)localNotice.value=e.message}finally{if(token===poolSerial)poolLoading.value=false}}
function cancelWait(show=true){requestSerial++;controller?.abort();controller=null;busy.value=false;if(show){props.context.chatMessages.push({role:'assistant',text:'已停止等待这次回答。需要时可以重新提问。',source:'操作提示'});scroll()}}

async function ask(text=props.context.chatDraft,extra={}){
 const question=String(text||'').trim();if(!question||busy.value||voicePhase.value!=='idle'||applying.value)return;stopSpeaking();const token=++requestSerial;const captured=basis();const profile=JSON.parse(JSON.stringify(props.context.profile));const history=props.context.chatMessages.map(m=>({role:m.role,content:m.text}));
 props.context.chatDraft='';props.context.chatMessages.push({role:'user',text:question});busy.value=true;localNotice.value='';controller=new AbortController();await scroll();
 try{const result=await api('chat',{question,history,profile,product_id:selected.value?.id,compare_id:peer.value?.id,state:props.context.assistantState||{},...extra},{signal:controller.signal});if(token!==requestSerial||disposed)return;
  const changed=captured!==basis();if(!changed)applyAdvisorTurn(props.context,pool.value,result,captured);
  const message={role:'assistant',text:result.answer,source:result.source,notice:[result.notice,changed?'这条回答基于提问时的需求，当前选择已变化；请按当前需求重新提问。':null].filter(Boolean).join(' '),data:result,basis:changed?captured:basis()};props.context.chatMessages.push(message);await scroll();if(autoSpeak.value)speak(result.answer);
 }catch(e){if(e.name!=='AbortError'&&token===requestSerial&&!disposed){props.context.chatMessages.push({role:'assistant',text:'这次请求没有成功：'+e.message+'。可以重试，或继续查看已核对的资料。',source:'连接提示'});await scroll()}}finally{if(token===requestSerial){busy.value=false;controller=null}}
}
function keydown(event){if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();ask()}}
async function ensureProducts(ids){let map=new Map([...pool.value,...props.context.products].map(p=>[p.id,p]));if(ids.some(id=>!map.has(id))){const result=await api('recommend',{...props.context.profile,purpose:'compare'});pool.value=result.products;map=new Map(result.products.map(p=>[p.id,p]))}const products=ids.map(id=>map.get(id));if(products.some(p=>!p))throw new Error('这些产品不在当前选购范围，请按当前需求重新提问');return products}
async function action(value,message){if(value.type==='quote'){quoteProduct.value=value.product;return}if(busy.value||applying.value||message&&stale(message))return;
 try{if(value.type==='confirm_profile'||value.type==='keep_profile'){await ask(value.type==='confirm_profile'?'确认调整预算':'保持原预算',{confirmation:value.type==='confirm_profile'?'apply':'reject'});return}
  if(value.type==='compare'||value.type==='report'){const ids=value.type==='compare'?value.product_ids:[value.product_id,value.compare_id].filter((id,i,list)=>id&&list.indexOf(id)===i);const products=await ensureProducts(ids);const next=prepareNavigation(props.context,value,products);emit('navigate',next.tab,next.product)}
 }catch(e){ElMessage.error(e.message)}
}
function beginEdit(){Object.assign(edit,props.context.profile);editing.value=true}
async function applyRequirements(){if(busy.value)cancelWait(false);applying.value=true;try{const changedScenario=edit.scenario!==props.context.profile.scenario;const cleaned=String(edit.needs||'').replace(/预算[约为是:：]*\s*\d+(?:\.\d+)?\s*(?:元|块|千|万|[kK])?/g,'').replace(/\d+(?:\.\d+)?\s*(?:元|块)(?:以内|左右|以下)?/g,'');const next={...props.context.profile,...edit,needs:'预算'+money(edit.budget)+'，选购'+edit.category+'，主要用于'+edit.scenario+'。'+cleaned,subcategory:null,weights:changedScenario?scenarioWeights(edit.scenario):props.context.profile.weights};const result=await api('recommend',{...next,purpose:'compare'});Object.assign(props.context.profile,next);pool.value=result.products;props.context.products=result.products;props.context.selectedId=result.products.find(p=>p.recommendation_eligible)?.id||null;props.context.comparePair=[];props.context.assistantState={};props.context.assistantSuggestions=[];props.context.reportDocument=null;props.context.pendingPrice=result.pending_price;props.context.overBudget=result.over_budget;props.context.process=result.process;localNotice.value='当前需求已应用。下一条回答将使用这组预算、用途和关注重点。';editing.value=false}catch(e){ElMessage.error(e.message)}finally{applying.value=false}}
function chooseFocus(id){if(!id){props.context.selectedId=null;props.context.comparePair=[];props.context.assistantState={};props.context.assistantSuggestions=[];return;}const p=options.value.find(p=>p.id===id);if(!p)return;props.context.selectedId=id;const other=peer.value&&peer.value.id!==id?peer.value:options.value.find(p=>p.id!==id&&p.recommendation_eligible);props.context.comparePair=[p,other].filter(Boolean);props.context.assistantState={};props.context.assistantSuggestions=[]}
function choosePeer(id){const other=options.value.find(p=>p.id===id);props.context.comparePair=[selected.value,other].filter(Boolean);props.context.assistantState={};props.context.assistantSuggestions=[]}
function clearChat(){cancelWait(false);voice.cancel();stopSpeaking();props.context.chatMessages=[];props.context.chatDraft='';props.context.assistantState={};props.context.assistantSuggestions=[];localNotice.value='已开启新对话，当前选购需求仍保留。'}
watch(()=>JSON.stringify(props.context.profile),()=>{clearTimeout(poolTimer);poolTimer=setTimeout(loadPool,200)});
onMounted(()=>{if(props.context.assistantScope&&props.context.assistantScope!==basis()){props.context.assistantState={};props.context.assistantSuggestions=[]}refresh();loadPool();scroll()});onBeforeUnmount(()=>{disposed=true;cancelWait(false);poolSerial++;clearTimeout(poolTimer);voice.dispose();stopSpeaking()});
</script>
<template>
<section class="assistant-page advisor-page"><div class="page-heading"><div><span class="eyebrow">YOUR SHOPPING ADVISOR</span><h1>把疑问，聊成更清楚的选择</h1><p>沿用你的预算与用途，解释推荐、核对报价，再把选择带到对比与报告。</p></div><button class="secondary-btn" @click="settingsOpen=true"><UiIcon name="settings" :size="17"/>模型设置</button></div>
 <div class="advisor-workspace"><aside class="advisor-context panel"><div class="advisor-context-title"><span><UiIcon name="spark" :size="17"/>当前选购</span><button @click="beginEdit">修改需求</button></div><template v-if="!editing"><div class="advisor-budget"><small>预算上限</small><strong>{{money(context.profile.budget)}}</strong><p>{{context.profile.category}} · {{context.profile.scenario}}</p></div><p class="advisor-needs">{{context.profile.needs}}</p><div class="advisor-priorities"><span v-for="[k,v] in priorities" :key="k">{{metricNames[k]}} {{v}}</span></div><div class="advisor-priority-shortcuts"><button :disabled="busy" @click="ask('更看重续航，重新筛选')">续航优先</button><button :disabled="busy" @click="ask('更看重轻便，重新筛选')">轻便优先</button></div><label>当前讨论对象<el-select :model-value="context.selectedId" filterable clearable :loading="poolLoading" :disabled="busy" placeholder="可先直接提问" @change="chooseFocus"><el-option v-for="p in options" :key="p.id" :label="p.name" :value="p.id"/></el-select></label><label>另一款产品<el-select :model-value="peer?.id" filterable clearable :disabled="busy" placeholder="可选：两款一起比较" @change="choosePeer"><el-option v-for="p in options.filter(p=>p.id!==context.selectedId)" :key="p.id" :label="p.name" :value="p.id"/></el-select></label><div v-if="selected" class="advisor-focus"><small>正在核对</small><b>{{selected.name}}</b><span>{{selected.budget_status}}</span></div><div class="advisor-context-links"><button :disabled="!selected||busy" @click="action({type:'compare',product_ids:[selected.id,peer?.id].filter(Boolean)})">产品对比 ↗</button><button :disabled="!selected||busy" @click="action({type:'report',product_id:selected.id,compare_id:peer?.id})">购买报告 ↗</button></div></template>
 <div v-else class="advisor-edit"><label>产品类别<el-select v-model="edit.category"><el-option v-for="c in categories" :key="c" :label="c" :value="c"/></el-select></label><label>预算上限<el-input-number v-model="edit.budget" :min="1" :max="50000" :step="100"/></label><label>主要用途<el-select v-model="edit.scenario"><el-option v-for="s in ['老人使用','学习','办公','游戏']" :key="s" :label="s" :value="s"/></el-select></label><label>需求补充<textarea v-model="edit.needs" maxlength="1000" rows="4"></textarea></label><div><button class="primary-btn" :disabled="applying" @click="applyRequirements">{{applying?'核对中…':'应用需求'}}</button><button class="text-btn" :disabled="applying" @click="editing=false">取消</button></div></div>
 <div class="advisor-connection"><i :class="{ready:latestMode==='model'}"></i><span>{{latestMode==='model'?'本次对话已有真实模型回答':status.configured?'模型服务已配置':'本地模式 · 可连接大模型'}}<small>{{status.configured?status.model:'当前回答使用本地产品资料'}}</small></span></div><button class="advisor-new-chat" @click="clearChat">开启新对话 <UiIcon name="refresh" :size="13"/></button></aside>
 <div class="conversation-panel panel advisor-conversation"><div class="conversation-top"><span><i></i>SmartBuy · 选购顾问</span><div class="advisor-conversation-tools"><button v-if="speaking" @click="stopSpeaking">停止朗读</button><label v-if="canSpeak&&!speaking"><input type="checkbox" v-model="autoSpeak"/>朗读回答</label><span>{{status.configured?'已配置模型':'本地资料核对'}}</span></div></div><div ref="chatEl" class="conversation-scroll"><div v-if="!context.chatMessages.length" class="advisor-welcome"><div class="advisor-welcome-symbol"><UiIcon name="spark" :size="34"/></div><span class="eyebrow">GOOD QUESTIONS, BETTER CHOICES</span><h2>你关心什么，我们就从哪里开始。</h2><p>当前预算 {{money(context.profile.budget)}}，主要用于{{context.profile.scenario}}。<br>可以直接说“它”“另一款”，也可以提出新的选购要求。</p><div class="prompt-grid"><button v-for="q in suggestions" :key="q" @click="ask(q)">{{q}}<span>↗</span></button></div><small>预算调整先确认；未核实的信息会单独说明。</small></div>
 <div v-for="(message,i) in context.chatMessages" :key="i" :class="['chat-message',message.role]"><span class="message-avatar">{{message.role==='assistant'?'✦':'我'}}</span><div class="message-content"><small>{{message.role==='assistant'?'SmartBuy 选购顾问':'你'}}</small><AssistantAnswer v-if="message.role==='assistant'" :message="message" :disabled="busy||stale(message)" @action="action($event,message)"/><div v-else class="advisor-user-text">{{message.text}}</div><div v-if="message.role==='assistant'" class="message-meta"><span>{{message.source}}</span><button v-if="canSpeak" @click="speak(message.text)" aria-label="朗读这条回答"><UiIcon name="speaker" :size="15"/></button></div><p v-if="message.notice" class="message-notice">{{message.notice}}</p><button v-if="stale(message)" class="advisor-stale" :disabled="busy" @click="ask('按当前预算和用途，重新核对推荐')">按当前需求重新核对 ↗</button></div></div><div v-if="busy" class="thinking" role="status"><i></i><i></i><i></i><span>正在核对资料与组织回答…</span><button @click="cancelWait()">停止等待</button></div></div>
 <div class="composer advisor-composer"><div v-if="context.chatMessages.length&&!busy" class="advisor-followup-chips"><button v-for="q in suggestions.slice(0,3)" :key="q" :disabled="voicePhase!=='idle'" @click="ask(q)">{{q}} ↗</button></div><p v-if="localNotice" class="advisor-local-notice" role="status">{{localNotice}}</p><div v-if="voicePhase!=='idle'" class="advisor-recording"><span class="voice-wave"><i></i><i></i><i></i><i></i></span><b>{{voicePhase==='requesting'?'等待麦克风权限':voicePhase==='listening'?'正在听 · '+voiceElapsed+'s':voicePhase==='transcribing'?'正在转成文字':'正在结束语音'}}</b><button @click="voice.cancel">取消本次语音</button></div><p v-if="voiceNotice" class="voice-notice" role="status">{{voiceNotice}}</p><textarea v-model="context.chatDraft" aria-label="向智能助手提问" placeholder="例如：另一款续航怎么样？换个便宜点的？ Shift + Enter 换行" maxlength="3000" :disabled="voicePhase!=='idle'" @keydown="keydown"></textarea><div class="composer-tools"><div><button :class="['voice-button',voicePhase==='listening'&&'recording']" :disabled="busy||!['idle','listening'].includes(voicePhase)" @click="voiceClick"><UiIcon :name="voicePhase==='listening'?'stop':'mic'" :size="17"/>{{voicePhase==='listening'?'结束语音':'语音输入'}}</button><select v-model="voiceMode" :disabled="voicePhase!=='idle'" aria-label="语音输入方式"><option value="browser" :disabled="!voice.supported">浏览器语音识别</option><option value="record">录音转文字</option></select></div><button class="primary-btn send-button" :disabled="busy||applying||!context.chatDraft.trim()||voicePhase!=='idle'" @click="ask()">发送<UiIcon name="send" :size="16"/></button></div><p class="advisor-composer-note">{{voiceMode==='record'?'录音结束后交给所配置服务转写，确认文字后再发送。':'语音识别由浏览器提供；文字可修改，确认后再发送。'}}</p></div></div></div>
 <el-drawer v-model="settingsOpen" title="连接你的大模型" size="min(470px,94vw)" @closed="settings.api_key=''"><div class="model-settings"><p class="muted">支持兼容的对话服务。未配置时可使用本地产品核对；配置后，每条回答会标明实际使用的方式。</p><label>API 服务地址<el-input v-model="settings.base_url" placeholder="https://api.openai.com/v1"/></label><label>对话模型名称<el-input v-model="settings.model" placeholder="填写服务提供的模型名称"/></label><label>API 密钥<el-input v-model="settings.api_key" type="password" show-password :placeholder="status.key_present?'已保存，留空保留原密钥':'仅保存在本机后端'" autocomplete="off"/></label><details><summary>语音转写设置</summary><label>转写模型名称<el-input v-model="settings.transcription_model" placeholder="填写音频转写模型名称"/></label><p class="muted small">录音转文字需要服务支持音频接口，聊天可用不代表语音接口已可用。</p></details><p class="muted small">密钥不写入对话、报告或浏览器存储。真实调用成功后才显示大模型回答标签。</p><p v-if="connection" class="connection-result" role="status">{{connection}}</p><div class="settings-actions"><button class="secondary-btn" :disabled="testing||saving" @click="test">{{testing?'测试中…':'测试连接'}}</button><button class="primary-btn" :disabled="saving||testing" @click="save">{{saving?'保存中…':'保存设置'}}</button></div></div></el-drawer>
 <el-drawer :model-value="!!quoteProduct" :title="quoteProduct?.name+' · 报价与资料'" size="min(520px,96vw)" @close="quoteProduct=null"><div v-if="quoteProduct" class="advisor-proof-drawer"><ProductImage :product="quoteProduct"/><h3>{{quoteProduct.name}}</h3><p>{{quoteProduct.budget_status}} · {{money(quoteProduct.price)}}</p><template v-if="quoteProduct.offer"><h4>本次核对的配置</h4><p>{{quoteProduct.offer.variant}}</p><p>{{quoteProduct.offer.merchant}} · {{quoteProduct.offer.price_type}}</p><p>采集于 {{observed(quoteProduct.offer.observed_at)}}</p><p>{{quoteProduct.offer.conditions}}</p><a :href="quoteProduct.offer.source_url" target="_blank" rel="noopener noreferrer">查看报价原文 ↗</a></template><p v-else>目前没有有效配置报价，不能确认是否符合预算。可按完整型号到平台核对。</p><ShoppingLinks :product="quoteProduct"/><div v-if="quoteProduct.source_url" class="advisor-original-source"><a :href="quoteProduct.source_url" target="_blank" rel="noopener noreferrer">产品原始资料 ↗</a><p v-if="quoteProduct.parameter_region_note">{{quoteProduct.parameter_region_note}}</p></div></div></el-drawer>
</section>
